func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/contacts", wrapper.ListContacts)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/contacts", wrapper.CreateContact)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/contacts/{contact_id}", wrapper.ShowContact)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/conversations", wrapper.ListConversations)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/conversations/{conversation_id}", wrapper.RetrieveConversation)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/conversations/{conversation_id}", wrapper.UpdateConversation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/conversations/{conversation_id}/reply", wrapper.ReplyConversation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.IdentifyAdmin)

	return m
}

